CREATE TABLE stage_artifacts(run_id TEXT PRIMARY KEY REFERENCES stage_runs(id),task_id TEXT NOT NULL REFERENCES tasks(id),record_json TEXT NOT NULL,record_hash TEXT NOT NULL);
CREATE TRIGGER immutable_stage_artifacts BEFORE UPDATE ON stage_artifacts BEGIN SELECT RAISE(ABORT,'immutable stage artifact'); END;
CREATE TRIGGER preserve_stage_artifacts BEFORE DELETE ON stage_artifacts BEGIN SELECT RAISE(ABORT,'preserve stage artifact'); END;
CREATE TRIGGER validate_stage_artifact BEFORE INSERT ON stage_artifacts WHEN NOT EXISTS(SELECT 1 FROM stage_runs r JOIN tasks t ON t.id=r.task_id JOIN reservations v ON v.run_id=r.id WHERE r.id=NEW.run_id AND r.task_id=NEW.task_id AND r.state='succeeded' AND r.startup_intent=1 AND r.launch_confirmed=1 AND r.lease_owner='' AND r.native_session_id!='' AND t.state='ready' AND t.generation=r.generation AND t.plan_revision=r.plan_revision AND json_extract(NEW.record_json,'$.reference.binding.run_id')=r.id AND json_extract(NEW.record_json,'$.reference.binding.task_id')=t.id AND json_extract(NEW.record_json,'$.reference.binding.role')=r.role AND json_extract(NEW.record_json,'$.reference.binding.generation')=r.generation AND json_extract(NEW.record_json,'$.reference.binding.plan_revision')=r.plan_revision AND (v.state='held' OR (v.state='released' AND v.stop_proof_hash=json_extract(NEW.record_json,'$.reference.stop_proof_hash')))) BEGIN SELECT RAISE(ABORT,'artifact requires current stopped successful run'); END;
PRAGMA user_version=10;
